// Cloudflare Pages runs `node src/build.mjs` with output folder `dist`.
// Pages are generated by src/build.py; if Python isn't available the committed dist/ is used as is.
import { spawnSync } from 'node:child_process';
import { existsSync } from 'node:fs';
const r = spawnSync('python3', ['src/build.py'], { stdio: 'inherit' });
if (r.status !== 0) {
  if (existsSync('dist/index.html')) console.log('python3 unavailable; using committed dist/');
  else process.exit(1);
}
